func (c *Config) legacyStoreScopeCredential() string {
	if c == nil {
		return ""
	}
	if header := c.AuthHeader(); header != "" {
		return header
	}

	var parts []string
	if c.AuthHeaderVal != "" {
		parts = append(parts, "auth_header="+c.AuthHeaderVal)
	}
	if c.RefreshToken != "" {
		parts = append(parts, "refresh_token="+c.RefreshToken)
	}
	if c.AccessToken != "" {
		parts = append(parts, "access_token="+c.AccessToken)
	}
	if c.ClientID != "" {
		parts = append(parts, "client_id="+c.ClientID)
	}
	if c.ClientSecret != "" {
		parts = append(parts, "client_secret="+c.ClientSecret)
	}
	if c.DattoRmmApiKey != "" {
		parts = append(parts, "rmm_api_key="+c.DattoRmmApiKey)
	}
	if c.DattoRmmApiSecretKey != "" {
		parts = append(parts, "rmm_api_secret_key="+c.DattoRmmApiSecretKey)
	}
	if c.DattoRmmToken != "" {
		parts = append(parts, "rmm_token="+c.DattoRmmToken)
	}
	if len(parts) == 0 {
		return ""
	}
	return strings.Join(parts, "\n")
}

